#!/usr/bin/bash
#
# Efficiency experiments (RQ3, RQ4, RQ5).
#
#   1. build the python virtual environment (for plot.py)
#   2. run cmm_perf over the artificial instances, appending to rq<N>_out.tsv
#   3. plot the results into plots/
#
# Instances are generated by ../data/run.sh and read from
# ../data/artificial_instances/. Run that first if they are not present.
#
# Usage:
#   ./run.sh              # run experiments, then plot
#   ./run.sh --plot-only  # re-plot existing TSVs without running anything

set -euo pipefail

cd "$(dirname "$0")"

INSTANCE_DIR="../data/artificial_instances"
CMM_PERF="./cmm_perf"
PLOT="./plot.py"
VENV="venv"
PLOT_DIR="plots"

OUT_RQ3="rq3_out.tsv"
OUT_RQ4="rq4_out.tsv"
OUT_RQ5="rq5_out.tsv"

MAX_THREADS=128
TRIALS=1
K=10000

RQ5_ELL=8
RQ5_D=2

source ../experiments.conf

V_MAX=$(echo ${NODE_COUNTS} | tr ' ' '\n' | sort -n | tail -1)

# RQ5 thread counts: start at 1 and double up to MAX_THREADS.
rq5_thread_counts() {
    local threads=""
    local t=1
    while [ ${t} -lt ${MAX_THREADS} ]
    do
        threads="${threads} ${t}"
        t=$(( t * 2 ))
    done
    echo "${threads} ${MAX_THREADS}"
}

case "${MAX_THREADS}" in
    ''|*[!0-9]*) echo "Error: MAX_THREADS must be a positive integer." >&2; exit 1 ;;
esac
[ "${MAX_THREADS}" -ge 1 ] || { echo "Error: MAX_THREADS must be >= 1." >&2; exit 1; }

PLOT_ONLY=0
if [ "$#" -gt 0 ]
then
    case "$1" in
        --plot-only) PLOT_ONLY=1 ;;
        *) echo "Usage: $0 [--plot-only]" >&2; exit 1 ;;
    esac
fi

# Setup virtual environment
if [ ! -d "${VENV}" ]
then
    echo "Creating virtual environment..." >&2
    python3 -m venv ${VENV}
    ${VENV}/bin/pip install -q -r requirements.txt
fi
source ${VENV}/bin/activate

run_cmm_perf() {
    local tsv=$1
    local trial=$2
    local fa=$3
    local int=$4
    local ell=$5
    local d=$6
    local threads=$7

    local key=$(basename ${fa} .fa)

    if [ ! -f "${fa}" ] || [ ! -f "${int}" ]
    then
        echo "Error: missing instance ${fa} / ${int}. Run ../data/run.sh first." >&2
        exit 1
    fi

    # TSV columns after prepended trial number:
    # 1:trial 2:instance 3:edge_density 4:V 5:N 6:ell 7:d
    # 8:max_rank 9:min_rank 10:avg_rank 11:pruning_cnt
    # 12:num_threads_requested 13:num_threads_spawned 14:time_ms 15:peak_ram_kb
    local uniq_pattern="${trial}|${key}|${ell}|${d}|${threads}"
    if [ -f "${tsv}" ] && (cut -f 1,2,6,7,12 ${tsv} | tr '\t' '|' | grep -qxF "${uniq_pattern}")
    then
        echo "Skipping trial=${trial} ${key} ell=${ell} d=${d} threads=${threads} -- already done" >&2
        return
    fi

    echo "Running trial=${trial} ${key} ell=${ell} d=${d} threads=${threads}" >&2
    ${CMM_PERF} ${fa} ${int} ${ell} ${d} ${K} ${threads} /dev/null \
        | awk -v trial=${trial} '{print trial "\t" $0}' >> ${tsv}
}

if [ ${PLOT_ONLY} -eq 0 ]
then
    ## Check that the binary and instances are present
    if [ ! -x "${CMM_PERF}" ]
    then
        echo "Error: ${CMM_PERF} not found or not executable. Run 'make' first." >&2
        exit 1
    fi
    if [ ! -d "${INSTANCE_DIR}" ]
    then
        echo "Error: ${INSTANCE_DIR} not found. Run ../data/run.sh first." >&2
        exit 1
    fi

    ## RQ3
    echo "Running experiment for RQ3..." >&2
    ED=05
    for trial in $(seq 1 ${TRIALS})
    do
        for v in ${NODE_COUNTS}
        do
            fa="${INSTANCE_DIR}/ed${ED}/sampled_${INSTANCE_TAXID}_V${v}_ed${ED}.fa"
            int="${INSTANCE_DIR}/ed${ED}/sampled_${INSTANCE_TAXID}_V${v}_ed${ED}.int"

            ell=5
            for d in 0 1 2 3 4
            do
                run_cmm_perf ${OUT_RQ3} ${trial} ${fa} ${int} ${ell} ${d} ${MAX_THREADS}
            done

            ell=8
            for d in 0 1 2 3 4 5 6 7
            do
                run_cmm_perf ${OUT_RQ3} ${trial} ${fa} ${int} ${ell} ${d} ${MAX_THREADS}
            done
        done
    done

    ## RQ4
    echo "Running experiment for RQ4..." >&2
    V=${V_MAX}
    for trial in $(seq 1 ${TRIALS})
    do
        for ed in ${DENSITIES}
        do
            fa="${INSTANCE_DIR}/ed${ed}/sampled_${INSTANCE_TAXID}_V${V}_ed${ed}.fa"
            int="${INSTANCE_DIR}/ed${ed}/sampled_${INSTANCE_TAXID}_V${V}_ed${ed}.int"

            ell=5
            for d in 0 1 2 3 4
            do
                run_cmm_perf ${OUT_RQ4} ${trial} ${fa} ${int} ${ell} ${d} ${MAX_THREADS}
            done

            ell=8
            for d in 0 1 2 3 4 5 6 7
            do
                run_cmm_perf ${OUT_RQ4} ${trial} ${fa} ${int} ${ell} ${d} ${MAX_THREADS}
            done
        done
    done

    ## RQ5
    echo "Running experiment for RQ5..." >&2
    ED=05
    V=${V_MAX}
    for trial in $(seq 1 ${TRIALS})
    do
        for t in $(rq5_thread_counts)
        do
            fa="${INSTANCE_DIR}/ed${ED}/sampled_${INSTANCE_TAXID}_V${V}_ed${ED}.fa"
            int="${INSTANCE_DIR}/ed${ED}/sampled_${INSTANCE_TAXID}_V${V}_ed${ED}.int"
            run_cmm_perf ${OUT_RQ5} ${trial} ${fa} ${int} ${RQ5_ELL} ${RQ5_D} ${t}
        done
    done

    echo "Experiments for RQ3, RQ4, and RQ5 done." >&2
fi

## Plot
echo "Plotting results..." >&2
mkdir -p ${PLOT_DIR}

# (ell:d) pairs annotated with max_rank on the time plots.
ANNOTATE="8:4 8:7 5:2 5:4"
# (ell:d) pairs given a polynomial fit on the RQ3 plots.
POLY_PAIRS="5:1 5:3 8:2 8:5"

# RQ3: log-scale both axes, quadratic fit on time, linear fit on memory.
if [ ! -s "${OUT_RQ3}" ]
then
    echo "  ${OUT_RQ3} missing or empty, skipping rq3 plots" >&2
else
    echo "  rq3" >&2
    ${PLOT} \
        --input ${OUT_RQ3} \
        --rq rq3 \
        --output ${PLOT_DIR}/rq3 \
        --log-scale-time \
        --log-scale-mem \
        --fit-poly-time ${POLY_PAIRS} \
        --fit-poly-mem ${POLY_PAIRS} \
        --poly-degree-time 2 \
        --poly-degree-mem 1 \
        --no-poly-label \
        --max-rank ${ANNOTATE}
fi

# RQ4: annotate selected points with max_rank (linear axes, no fits).
if [ ! -s "${OUT_RQ4}" ]
then
    echo "  ${OUT_RQ4} missing or empty, skipping rq4 plots" >&2
else
    echo "  rq4" >&2
    ${PLOT} \
        --input ${OUT_RQ4} \
        --rq rq4 \
        --output ${PLOT_DIR}/rq4 \
        --max-rank ${ANNOTATE}
fi

# RQ5: speedup labels, log-scale both axes.
if [ ! -s "${OUT_RQ5}" ]
then
    echo "  ${OUT_RQ5} missing or empty, skipping rq5 plots" >&2
else
    echo "  rq5" >&2
    ${PLOT} \
        --input ${OUT_RQ5} \
        --rq rq5 \
        --output ${PLOT_DIR}/rq5 \
        --speedup \
        --rq5-ell ${RQ5_ELL} \
        --log-scale-time \
        --log-scale-mem
fi

echo "Done. Plots written to ${PLOT_DIR}/" >&2
